// Generated by `python manage.py generate_types`. Do not edit by hand.
//
// Derived from the schemas in backend/funding/schemas/. Renaming a field
// there breaks this build, which is the point: the frontend holds no
// opinion about what a field is called.

/** Every kind of application the portal accepts. */
export type ApplicationType =
  | 'admission'
  | 'enrollment_verification'
  | 'continuing_funding'
  | 'appeal'
  | 'travel'
  | 'practicum'
  | 'graduation_bursary'
  | 'emergency_relief'
  | 'hardship_bursary'
  | 'academic_scholarship';

export const APPLICATION_TYPE_LABELS: Record<ApplicationType, string> = {
  admission: "Admission Application",
  enrollment_verification: "Enrollment Verification",
  continuing_funding: "Continuing Funding",
  appeal: "Appeal / Reconsideration",
  travel: "Travel & Emergency Assistance",
  practicum: "Practicum Placement Allowance",
  graduation_bursary: "Graduation Bursary",
  emergency_relief: "Emergency Relief",
  hardship_bursary: "Hardship Bursary",
  academic_scholarship: "Academic Scholarship",
};

export type FieldType =
  | 'text'
  | 'long_text'
  | 'email'
  | 'phone'
  | 'date'
  | 'money'
  | 'integer'
  | 'percent'
  | 'choice'
  | 'boolean'
  | 'file'
  | 'signature';

/** One question, as the API describes it. */
export interface SchemaField {
  key: string;
  label: string;
  type: FieldType;
  required: boolean;
  help_text: string;
  section: string;
  choices: Array<{ value: string; label: string }>;
}

export interface ApplicationSchema {
  slug: ApplicationType;
  label: string;
  sections: string[];
  fields: SchemaField[];
}

