/** Answer shape for a given application type. */
export interface AnswersByType {
  academic_scholarship: AcademicScholarshipAnswers;
  admission: AdmissionAnswers;
  appeal: AppealAnswers;
  continuing_funding: ContinuingFundingAnswers;
  emergency_relief: EmergencyReliefAnswers;
  enrollment_verification: EnrollmentVerificationAnswers;
  graduation_bursary: GraduationBursaryAnswers;
  hardship_bursary: HardshipBursaryAnswers;
  practicum: PracticumAnswers;
  travel: TravelAnswers;
}

export type AnswersFor<T extends ApplicationType> = AnswersByType[T];
